package com.dreamfacilities.servlet;
import com.dreamfacilities.dao.FeedbackDAO; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet("/feedback") public class FeedbackServlet extends HttpServlet { protected void doGet(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/submit.jsp").forward(q,r);} protected void doPost(HttpServletRequest q,HttpServletResponse r)throws ServletException,IOException{q.setCharacterEncoding("UTF-8");String name=clean(q.getParameter("name")),email=clean(q.getParameter("email")),subject=clean(q.getParameter("subject")),message=clean(q.getParameter("message"));int rating=0;try{rating=Integer.parseInt(q.getParameter("rating"));}catch(Exception ignored){}if(name.isBlank()||email.isBlank()||subject.isBlank()||message.isBlank()||rating<1||rating>5){q.setAttribute("error","Please complete every field and select a rating.");q.getRequestDispatcher("/WEB-INF/views/submit.jsp").forward(q,r);return;}try{new FeedbackDAO().add(name,email,subject,message,rating);r.sendRedirect(q.getContextPath()+"/feedback?success=1");}catch(Exception e){q.setAttribute("error","Could not save feedback. Check your database setup and try again.");q.getRequestDispatcher("/WEB-INF/views/submit.jsp").forward(q,r);}}private String clean(String s){return s==null?"":s.trim();} }
